const now = new Date();
const hour = now.getUTCHours();
const minute = now.getUTCMinutes();
const day = now.getUTCDay(); // 0=Sun, 1=Mon

// Default: run waitlist promotion every cycle
let job_type = 'WAITLIST_PROMOTION';

// Every day at 09:00 UTC → ops reports
if (minute === 0 && hour === 9 && day === 1) {
  job_type = 'WEEKLY_OPS_REPORT';
} else if (minute === 0 && hour === 9) {
  job_type = 'DAILY_OPS_REPORT';
}
// Every day at 08:00 UTC → refund escalation
else if (minute === 0 && hour === 8) {
  job_type = 'REFUND_ESCALATION';
}
// Every day at 07:00 UTC → recent fraud scan
else if (minute === 0 && hour === 7) {
  job_type = 'RECENT_FRAUD_SCAN';
}
// Every Sunday at 06:00 UTC → historical fraud review
else if (minute === 0 && hour === 6 && day === 0) {
  job_type = 'HISTORICAL_FRAUD_REVIEW';
}
// Every hour on the hour → check-in reminders
else if (minute === 0) {
  job_type = 'CHECKIN_REMINDER';
}
// Every 6 hours at :30 → price-drop alerts
else if (minute === 30 && [0, 6, 12, 18].includes(hour)) {
  job_type = 'PRICE_DROP_ALERT';
}

return [{ json: { job_type, run_at: now.toISOString() } }];

