  return `${x.flight_number} | ${x.origin}→${x.destination} | Bookings: ${x.bookings_this_week} | Load: ${load}% | Revenue: $${rev} | Cancellations: ${x.cancellations} | Refunds: ${x.refunds_issued}`;
});
const week = new Date().toISOString().split('T')[0];
const totalRev = items.reduce((s, i) => s + Number(i.json.weekly_revenue || 0), 0);
const report = `📈 SkyFlow Weekly Operations Report — Week of ${week}\n${'═'.repeat(80)}\n${rows.join('\n')}\n${'═'.repeat(80)}\nTotal Weekly Revenue: $${totalRev.toFixed(2)} USD\nTotal Flights: ${rows.length}\nGenerated: ${new Date().toISOString()}`;
return [{ json: { report } }];

return items.map(i => {
  const b = i.json;
  const count = Number(b.passenger_count || 1);
  const amount = Number(b.total_amount || 0);
  const perSeat = count > 0 ? amount / count : amount;

  let risk_score = 0;
  let risk_flags = [];

  // Flag: large group booking (>= 5 pax)
  if (count >= 5) { risk_score += 40; risk_flags.push('LARGE_GROUP'); }
  // Flag: very high spend
  if (amount > 10000) { risk_score += 30; risk_flags.push('HIGH_SPEND'); }
  // Flag: unusually high per-seat spend
  if (perSeat > 3000) { risk_score += 20; risk_flags.push('HIGH_PER_SEAT'); }
  // Flag: booking made at unusual hour (2-5 AM UTC)
  const bookingHour = new Date(b.created_at).getUTCHours();
  if (bookingHour >= 2 && bookingHour <= 5) { risk_score += 15; risk_flags.push('UNUSUAL_HOUR'); }
  // Flag: no-name (anonymous) booking
  if (!b.user_id) { risk_score += 25; risk_flags.push('ANONYMOUS_BOOKING'); }

  return { json: { ...b, risk_score, risk_flags: risk_flags.join(','), high_risk: risk_score >= 50 } };
});

// Filter out minor fluctuations: only alert if drop > 10% AND > $20 absolute
return items.filter(i => {
  const pct = Number(i.json.drop_pct || 0);
  const abs = Number(i.json.savings_per_seat || 0);
  return pct >= 10 && abs >= 20;
});

