const text = $json.policy_text || '';
const source = $json.policy_source || 'Unknown';
const version = $json.policy_version || 'v1';
const chunkSize = 900;
const overlap = 150;
const chunks = [];
for (let i = 0; i < text.length; i += chunkSize - overlap) {
  const chunk = text.slice(i, i + chunkSize);
  if (chunk.trim().length > 50) {
    chunks.push({
      json: {
        pageContent: chunk,
        metadata: {
          source,
          version,
          chunk_index: chunks.length,
          char_start: i
        }
      }
    });
  }
}
console.log(`Chunked policy into ${chunks.length} segments`);
return chunks;
